package io.github.inkee1.memoalarmbridge.core

import com.google.gson.Gson
import com.google.gson.JsonObject
import org.junit.Assert.*
import org.junit.Test
import java.io.IOException
import java.time.Instant

class SyncEngineTest {
    @Test fun rejectedOperationDoesNotBlockCorrectedDraft(){val r=Repo();val n=note("rejected draft");r.state=r.state.copy(records=mapOf(n.key to n));engine(r){q->SyncResponse(results=q.operations.map{MutationResult(it.operationId,0,"rejected",error="quota")})}.syncOnce();r.state=r.state.copy(records=mapOf(n.key to n.copy(payload=note("corrected").payload,version=Version(null,2))));engine(r){q->assertEquals("corrected",q.operations.single().payload["text"].asString);accepted(q)}.syncOnce();assertFalse(r.state.records.getValue(n.key).dirty)}
    @Test fun sharedSyncFixtureUsesSameTypedContract(){val root=com.google.gson.JsonParser.parseString(java.io.File(System.getProperty("fixtures.dir"),"sync.json").readText()).asJsonObject;for(key in listOf("note","alarm")){val m=Gson().fromJson(root[key],Mutation::class.java);validateMutation(m).requireValid();assertTrue(validId(m.operationId))}}
    private val gson=Gson()
    private val id="11111111-1111-4111-8111-111111111111"
    private val epoch="22222222-2222-4222-8222-222222222222"
    private class Repo:SyncPort {var state=SyncState(linked=true);var failWrite=false;override fun read()=state;override fun write(value:SyncState){if(failWrite)throw IOException("synthetic disk failure");state=value}}
    private fun note(text:String,revision:Long?=null,generation:Long=1)=LocalRecord("note",id,gson.toJsonTree(Note(id,text)).asJsonObject,Version(revision,generation))
    private fun mutation(record:LocalRecord,op:String="33333333-3333-4333-8333-333333333333")=Mutation(operationId=op,entityType=record.entityType,entityId=record.entityId,baseRevision=record.version.serverRevision?:0,action="upsert",payload=record.payload)
    private fun accepted(request:SyncRequest):SyncResponse {
        val m=request.operations.single();val e=Entity(m.entityType,m.entityId,1,m.payload)
        return SyncResponse(cursor=1,results=listOf(MutationResult(m.operationId,1,"stored",entity=e)),changes=listOf(RemoteChange(1,m)))
    }
    private fun engine(repo:Repo,call:(SyncRequest)->SyncResponse)=SyncEngine(repo,object:SyncTransport{override fun exchange(request:SyncRequest)=call(request)},{Instant.parse("2030-01-01T00:00:00Z")})
    @Test fun duplicateRetryStable(){val r=Repo();val n=note("first");r.state=r.state.copy(records=mapOf(n.key to n));var first:Mutation?=null;val e=engine(r){q->if(first==null){first=q.operations.single();throw IOException("response lost")}else{assertEquals(first,q.operations.single());accepted(q)}};try{e.syncOnce();fail()}catch(_:IOException){};assertEquals(1,r.state.inFlight.size);e.syncOnce();assertTrue(r.state.inFlight.isEmpty());assertFalse(r.state.records.getValue(n.key).dirty)}
    @Test fun localEditWhileSendingPreserved(){val r=Repo();val n=note("sent");r.state=r.state.copy(records=mapOf(n.key to n));engine(r){q->r.state=r.state.copy(records=mapOf(n.key to note("newer local edit",null,2)));accepted(q)}.syncOnce();val latest=r.state.records.getValue(n.key);assertEquals("newer local edit",latest.payload["text"].asString);assertTrue(latest.dirty);assertEquals(1L,latest.version.serverRevision);assertTrue(latest.version.localGeneration>2);val e=engine(r){q->assertEquals(1L,q.operations.single().baseRevision);assertEquals("newer local edit",q.operations.single().payload["text"].asString);throw IOException()};try{e.syncOnce()}catch(_:IOException){} }
    @Test fun staleRemoteCannotOverwriteDirtyLocal(){val r=Repo();val n=note("new local",3,5);r.state=r.state.copy(cursor=1,records=mapOf(n.key to n),inFlight=emptyMap());val old=mutation(note("old",1));engine(r){q->SyncResponse(cursor=2,results=q.operations.map{MutationResult(it.operationId,0,"rejected",error="test")},changes=listOf(RemoteChange(2,old)))}.syncOnce();assertEquals("new local",r.state.records.getValue(n.key).payload["text"].asString)}
    @Test fun conflictKeepsBothCopies(){val r=Repo();val n=note("local draft",1,2);r.state=r.state.copy(cursor=1,records=mapOf(n.key to n));engine(r){q->val remote=Entity("note",id,2,note("PC edit").payload);SyncResponse(cursor=2,results=listOf(MutationResult(q.operations.single().operationId,2,"conflict",conflictCurrent=remote)),changes=listOf(RemoteChange(2,mutation(note("PC edit")))))}.syncOnce();val saved=r.state.records.getValue(n.key);assertEquals("local draft",saved.payload["text"].asString);assertEquals("PC edit",saved.conflict!!.remote!!.payload["text"].asString);assertEquals(2,r.state.cursor);assertTrue(r.state.inFlight.isEmpty())}
    @Test fun offlineCancelRemainsPending(){val r=Repo();val rule=ScheduleRule(id,epoch,atUtc="2030-01-02T00:00:00Z",body="cancel me",enabled=false);val record=LocalRecord("schedule",id,gson.toJsonTree(rule).asJsonObject,Version(1,2));r.state=r.state.copy(records=mapOf(record.key to record));try{engine(r){throw IOException("offline")}.syncOnce();fail()}catch(_:IOException){};assertEquals("cancel",r.state.inFlight.getValue(record.key).operation.action);assertTrue(r.state.records.getValue(record.key).dirty)}
    @Test fun tombstoneOverridesOldEpoch(){val r=Repo();val rule=ScheduleRule(id,epoch,atUtc="2030-01-02T00:00:00Z",body="local draft");val record=LocalRecord("schedule",id,gson.toJsonTree(rule).asJsonObject,Version(1,2));r.state=r.state.copy(cursor=1,records=mapOf(record.key to record));val cancel=Mutation(operationId="33333333-3333-4333-8333-333333333334",entityType="schedule",entityId=id,baseRevision=1,action="cancel",payload=JsonObject().apply{addProperty("epoch_id",epoch)});engine(r){q->SyncResponse(cursor=2,results=q.operations.map{MutationResult(it.operationId,2,"cancelled")},changes=listOf(RemoteChange(2,cancel)))}.syncOnce();assertFalse(r.state.records.getValue(record.key).payload["enabled"].asBoolean);assertTrue("$id:$epoch" in r.state.cancelledEpochs);engine(r){SyncResponse(cursor=3,changes=listOf(RemoteChange(3,mutation(record))))}.syncOnce();assertFalse(r.state.records.getValue(record.key).payload["enabled"].asBoolean)}
    @Test fun unpairDoesNotPretendToCancelPhone(){val r=Repo();val n=note("keep",1,2).copy(dirty=false);r.state=r.state.copy(records=mapOf(n.key to n));engine(r){throw AssertionError("network during detach")}.detach();assertFalse(r.state.linked);assertEquals(n,r.state.records.getValue(n.key));assertTrue(r.state.cancelledEpochs.isEmpty())}
    @Test fun failedCommitDoesNotAdvanceCursor(){val r=Repo();val remote=mutation(note("remote"));val e=engine(r){r.failWrite=true;SyncResponse(cursor=1,changes=listOf(RemoteChange(1,remote)))};try{e.syncOnce();fail()}catch(_:IOException){};assertEquals(0,r.state.cursor);assertTrue(r.state.records.isEmpty())}
    @Test fun staleConflictChoiceRejected(){val r=Repo();val n=note("mine",1,2).copy(conflict=SyncConflict(Entity("note",id,3,note("theirs").payload),3));r.state=r.state.copy(records=mapOf(n.key to n));try{engine(r){throw AssertionError()}.resolve(n.key,true,2,2);fail("old conflict choice applied")}catch(_:IllegalArgumentException){};assertNotNull(r.state.records.getValue(n.key).conflict)}
    @Test fun oldConnectionResponseCannotApplyAfterRePair(){val r=Repo();val n=note("mine");r.state=r.state.copy(records=mapOf(n.key to n));lateinit var e:SyncEngine;e=engine(r){q->e.detach();e.attach(true);accepted(q)};try{e.syncOnce();fail("old server response applied to new connection")}catch(_:IllegalStateException){};assertNull(r.state.records.getValue(n.key).version.serverRevision);assertEquals(0L,r.state.cursor)}
    @Test fun disabledRemoteUpsertTombstonesEpoch(){val r=Repo();val rule=ScheduleRule(id,epoch,atUtc="2030-01-02T00:00:00Z",body="off",enabled=false);val record=LocalRecord("schedule",id,gson.toJsonTree(rule).asJsonObject,Version(null,1));engine(r){SyncResponse(cursor=1,changes=listOf(RemoteChange(1,mutation(record))))}.syncOnce();assertTrue("$id:$epoch" in r.state.cancelledEpochs);assertFalse(r.state.records.getValue(record.key).payload["enabled"].asBoolean)}
    @Test fun cancelConflictUsesLatestCancellationRevision(){val r=Repo();val rule=ScheduleRule(id,epoch,atUtc="2030-01-02T00:00:00Z",body="mine");val record=LocalRecord("schedule",id,gson.toJsonTree(rule).asJsonObject,Version(1,2));r.state=r.state.copy(cursor=1,records=mapOf(record.key to record));val cancel=Mutation(operationId="33333333-3333-4333-8333-333333333334",entityType="schedule",entityId=id,baseRevision=1,action="cancel",payload=JsonObject().apply{addProperty("epoch_id",epoch)});val e=engine(r){q->SyncResponse(cursor=2,results=q.operations.map{MutationResult(it.operationId,2,"cancelled")},changes=listOf(RemoteChange(2,cancel)))};e.syncOnce();val current=r.state.records.getValue(record.key);assertEquals(2L,current.conflict!!.revision);e.resolve(record.key,true,2,current.version.localGeneration);val kept=r.state.records.getValue(record.key);assertEquals(2L,kept.version.serverRevision);assertNotEquals(epoch,kept.payload["epoch_id"].asString);assertTrue(kept.payload["enabled"].asBoolean)}
    @Test fun cancelOldEpochDoesNotSilentlyOverwriteAnotherNewEpoch(){val r=Repo();val rule=ScheduleRule(id,epoch,atUtc="2030-01-02T00:00:00Z",body="old",enabled=false);val record=LocalRecord("schedule",id,gson.toJsonTree(rule).asJsonObject,Version(1,2));r.state=r.state.copy(cursor=1,records=mapOf(record.key to record));engine(r){q->val mine=rule.copy(epochId="22222222-2222-4222-8222-222222222223",body="my new alarm",enabled=true);r.state=r.state.copy(records=mapOf(record.key to record.copy(payload=gson.toJsonTree(mine).asJsonObject,version=Version(1,3))));val theirs=rule.copy(epochId="22222222-2222-4222-8222-222222222224",body="other device",enabled=true);SyncResponse(cursor=1,results=listOf(MutationResult(q.operations.single().operationId,3,"cancel_pending",entity=Entity("schedule",id,2,gson.toJsonTree(theirs).asJsonObject))))}.syncOnce();val saved=r.state.records.getValue(record.key);assertNotNull(saved.conflict);assertEquals("my new alarm",saved.payload["body"].asString);assertEquals("other device",saved.conflict!!.remote!!.payload["body"].asString)}
}
